## Consuming CDC Events in Spring

```java
@Component
public class OrderChangeCDCConsumer {

    @KafkaListener(topics = "appdb.public.orders", groupId = "search-indexer")
    public void handleOrderChange(@Payload Map<String, Object> event) {
        String operation = (String) event.get("op");
        Map<String, Object> after = (Map<String, Object>) event.get("after");
        Map<String, Object> before = (Map<String, Object>) event.get("before");

        switch (operation) {
            case "c", "u" -> {
                // Insert or Update: index the latest state
                Long orderId = ((Number) after.get("id")).longValue();
                searchIndexService.indexOrder(orderId, after);
            }
            case "d" -> {
                // Delete: remove from index
                Long orderId = ((Number) before.get("id")).longValue();
                searchIndexService.removeOrder(orderId);
            }
        }
    }
}
```

